overlays.body:
{
 "vendors": "local",
 "compress": "br",
 "cache": "revalidate",
 "root": "<HOME>/site-pretty",
 "baseline": {
  "snapshot": "<SNAPSHOT>",
  "state": "override"
 },
 "overlays": [
  {
   "dir": "<HOME>/ovA",
   "files": [
    "/_app/immutable/nodes/2.fixture.js",
    "/new-file.js"
   ]
  },
  {
   "dir": "<HOME>/ovB",
   "files": [
    "/_app/immutable/assets/0.fixture.css",
    "/_app/immutable/nodes/2.fixture.js"
   ]
  }
 ],
 "latency": 0,
 "https": false,
 "selfSigned": false,
 "httpTwin": null,
 "rewrites": [
  "index.html: + <script src=\"/__mirror/vendor-shim.js\"> before /analytics.js",
  "index.html: Cloudflare beacon src https://static.cloudflareinsights.com/… -> /__vendor/static.cloudflareinsights.com/…"
 ]
}
